    const allowedPos=new Set(['noun','verb','i-adjective','na-adjective','adverb','pronoun','conjunction','particle','expression','counter','particle/expression','interjection','prefix','suffix']);
    const allowedLevels=new Set(['N5','N4','N3','N2','N1','Unclassified']);
