      if(!w||typeof w!=='object')continue;
      if(w.source||w.sources||w.sourceUrl||w.provenance||w.jlptSource||w.jlptProvenance)sourceChecked.push(w.id);
      if(ids.has(w.id))dupIds.push(w.id);ids.add(w.id);
      const key=String(w.japanese||'').trim()+'|'+String(w.hiragana||'').trim();if(keys.has(key))dupPairs.push({key, id:w.id});keys.add(key);
      const misses=['id','japanese','hiragana','meaning','partOfSpeech'].filter(k=>typeof w[k]!=='string'||!String(w[k]).trim());if(w.jlpt==null||!allowedLevels.has(w.jlpt))misses.push('jlpt');if(!Array.isArray(w.categories))misses.push('categories');if(misses.length)missing.push({id:w.id||'',fields:misses});else hasCore.push(w.id);
      if(!allowedPos.has(w.partOfSpeech))invalidPos.push({id:w.id,pos:w.partOfSpeech});
      if(!allowedLevels.has(w.jlpt||'Unclassified'))invalidLevels.push({id:w.id,level:w.jlpt});
      const hiraganaPresent=/[\u3040-\u309f]/u.test(w.hiragana||'');if(!hiraganaPresent)readingReview.push({id:w.id,japanese:w.japanese,reading:w.hiragana,reason:'Bacaan tidak mengandung karakter hiragana; perlu pemeriksaan manual.'});
      const ex=Array.isArray(w.examples)?w.examples:[];totalExamples+=ex.length;if(ex.length)wordsWithExamples++;
      for(const e of ex){const status=e?.verificationStatus||w.exampleValidationStatus||'unreviewed';if(status==='legacy_unverified')legacyExamples++;else if(status==='ai_draft_pending_review')aiDraftExamples++;else if(status==='verified'||status==='human_verified')verifiedExamples++;else if(status==='source_checked')sourceExamples++;if(!e?.reading)examplesNoReading.push({id:w.id,japanese:e?.japanese||''});}
