  function v10StartAdaptive(mode='smart'){const words=v10RankedWords(mode);if(!words.length){setStatus('Tidak ada kartu sesuai mode ini.');return}const limit=Number(studyPrefs.v10DailyNewLimit||studyPrefs.dailyNewLimit||10);if(mode==='due'&&!words.some(w=>v10WordScore(w).due)){setStatus('Belum ada kartu adaptif yang jatuh tempo.');return}$('search').value='';$('jlptFilter').value='all';$('posFilter').value='all';$('categoryFilter').value='all';$('studyFilter').value='all';$('orderMode').value='ordered';applyFilters();const eligible=new Set(filteredWords.map(w=>w.id));const today=todayKey();const introduced=allWords.filter(w=>{const first=wordProgress(w).firstSeenAt;return first&&new Date(first).toLocaleDateString('sv-SE')===today}).length;const remainingNew=Math.max(0,limit-introduced);const sessionChoice=Number($('sessionLimit').value||20);const sessionCap=sessionChoice===0?Infinity:Math.max(1,sessionChoice);let ranked=words.filter(w=>eligible.has(w.id));if(mode==='new')ranked=ranked.filter(w=>{const p=wordProgress(w);return !p.firstSeenAt&&!p.reviewedAt&&!v10GetSrs(w.id).attempts}).slice(0,Math.min(sessionCap,remainingNew));else{let usedNew=0;ranked=ranked.filter(w=>{const p=wordProgress(w),isNew=!p.firstSeenAt&&!p.reviewedAt&&!v10GetSrs(w.id).attempts;if(isNew){if(usedNew>=remainingNew)return false;usedNew++}return true}).slice(0,sessionCap)}if(!ranked.length){setStatus(mode==='new'&&remainingNew===0?`Batas ${limit} kartu baru hari ini sudah tercapai.`:'Tidak ada kartu untuk sesi adaptif dengan pengaturan saat ini.');return}filteredWords=ranked;currentIndex=0;isBack=false;v3ShowView('learn');renderCard();const target=filteredWords[0];setStatus(`Sesi adaptif dimulai: ${filteredWords.length} kartu diurutkan menurut prioritas. Kartu pertama: ${target.japanese} (${target.meaning}). Batas kartu baru ${limit}/hari; ${introduced} sudah diperkenalkan hari ini.`)}

  function v10ChooseJapaneseVoice(){if(!('speechSynthesis'in window))return null;const voices=window.speechSynthesis.getVoices?.()||[];return voices.find(v=>/^ja(-|$)/i.test(v.lang))||voices.find(v=>/japanese|日本語/i.test(v.name))||null}
  function v10Speak(text, rateControl='v10SpeechRate', statusId='v10ListenStatus'){const target=String(text||'').trim();if(!target){v10SayStatus(statusId,'Tidak ada teks audio yang tersedia.',true);return false}if(!('speechSynthesis'in window)||!('SpeechSynthesisUtterance'in window)){v10SayStatus(statusId,'Text-to-speech tidak tersedia di browser/perangkat ini.',true);return false}try{window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(target);utterance.lang='ja-JP';utterance.rate=Math.min(1.4,Math.max(.55,Number($10(rateControl)?.value||1)));const voice=v10ChooseJapaneseVoice();if(voice)utterance.voice=voice;utterance.onstart=()=>v10SayStatus(statusId,voice?`Audio diputar dengan suara ${voice.name}.`:'Audio diputar memakai suara default browser; suara Jepang khusus belum terdeteksi.');utterance.onerror=e=>v10SayStatus(statusId,'Audio tidak dapat diputar: '+(e.error||'error browser'),true);utterance.onend=()=>{};window.speechSynthesis.speak(utterance);return true}catch(e){v10SayStatus(statusId,'Audio gagal dijalankan: '+(e.message||e),true);return false}}
