  function v10Shuffle(arr){return shuffle([...arr])}
  function v10ChoiceStrings(correct,distractors){return [...new Set([String(correct),...distractors.filter(x=>x!=null).map(String).filter(x=>String(x)!==String(correct))])].slice(0,4)}
  function v10MakeWordQ(w,category,level){let correct,other,prompt,targetText,targetReading='';if(category==='kanji'){correct=w.hiragana;other=allWords.filter(x=>x.id!==w.id&&(level==='all'||(x.jlpt||'Unclassified')===level)).map(x=>x.hiragana)}else{correct=w.meaning;other=allWords.filter(x=>x.id!==w.id&&(level==='all'||(x.jlpt||'Unclassified')===level)).map(x=>x.meaning)}const distractors=v10Shuffle([...new Set(other.filter(x=>x&&x!==correct))]).slice(0,3);const opts=v10Shuffle(v10ChoiceStrings(correct,distractors));targetText=w.japanese;targetReading=w.hiragana;prompt=category==='kanji'?'次の言葉の読み方はどれですか。':'次の言葉の意味は何ですか。';return {id:'q-'+category+'-'+w.id+'-'+Math.random().toString(36).slice(2,7),category,level,wordId:w.id,skill:category==='kanji'?'kanji':'meaning',prompt,targetText,targetReading,options:opts,answer:correct,rationale:category==='kanji'?`${w.japanese} の読み方は ${w.hiragana} です。`:`${w.japanese} は「${w.meaning}」という意味です。`}}
  function v10MakeGrammarQ(g,level){const opts=v10Shuffle(v10ChoiceStrings(g.options[g.answer],g.options.filter((_,i)=>i!==g.answer)));return {id:'q-grammar-'+g.id+'-'+Math.random().toString(36).slice(2,7),category:'grammar',level:g.level,skill:'grammar',lessonId:g.id,prompt:g.question,targetText:g.pattern,options:opts,answer:g.options[g.answer],rationale:g.explanation}}
  function v10MakeReadingQ(r){const opts=v10Shuffle(v10ChoiceStrings(r.options[r.answer],r.options.filter((_,i)=>i!==r.answer)));return {id:'q-reading-'+r.id+'-'+Math.random().toString(36).slice(2,7),category:'reading',level:r.level,skill:'reading',lessonId:r.id,prompt:r.question,targetText:r.text,options:opts,answer:r.options[r.answer],rationale:r.explanation}}
  function v10CreateQuestionPool(level,category){const levels=(w)=>level==='all'||(w.level||w.jlpt||'Unclassified')===level;const pool=[];const wordRows=allWords.filter(w=>(level==='all'||(w.jlpt||'Unclassified')===level)&&w.japanese&&w.hiragana&&w.meaning);
    if(category==='all'||category==='vocabulary')v10Shuffle(wordRows).forEach(w=>pool.push(v10MakeWordQ(w,'vocabulary',level)));
    if(category==='all'||category==='kanji')v10Shuffle(wordRows).forEach(w=>pool.push(v10MakeWordQ(w,'kanji',level)));
    if(category==='all'||category==='grammar')v10Shuffle(V10_GRAMMAR.filter(g=>level==='all'||g.level===level)).forEach(g=>pool.push(v10MakeGrammarQ(g,level)));
    if(category==='all'||category==='reading')v10Shuffle(V10_READINGS.filter(r=>level==='all'||r.level===level)).forEach(r=>pool.push(v10MakeReadingQ(r)));
    if(category==='all'||category==='listening')v10Shuffle(wordRows).forEach(w=>{const q=v10MakeWordQ(w,'vocabulary',level);q.id=q.id.replace('vocabulary','listening');q.category='listening';q.skill='listening';q.prompt='音声を聞いて、言葉の意味を選んでください。';q.targetText=w.japanese;q.rationale=`${w.japanese}（${w.hiragana}）: ${w.meaning}`;pool.push(q)});
    return v10Shuffle(pool);
  }
  function v10SelectExamQuestions(level,category,count){let pool=v10CreateQuestionPool(level,category);if(category==='all'){const buckets={};for(const q of pool)(buckets[q.category]||(buckets[q.category]=[])).push(q);const wanted=['vocabulary','kanji','grammar','reading','listening'];pool=[];let turn=0;while(pool.length<count&&wanted.some(k=>buckets[k]?.length)){const k=wanted[turn%wanted.length];if(buckets[k]?.length)pool.push(buckets[k].pop());turn++}return pool.slice(0,count)}return pool.slice(0,Math.min(count,pool.length))}
  function v10GetActiveExam(){const row=v3SkillProgress[V10_EXAM_META_KEY];return plain10(row)&&plain10(row.value)?row.value:null}
  function v10SaveActiveExam(exam){if(exam){v3SkillProgress[V10_EXAM_META_KEY]={attempts:0,correct:0,mistakes:0,interval:0,dueAt:0,repetitions:0,lastAt:Date.now(),history:[],value:clone10(exam)}}else delete v3SkillProgress[V10_EXAM_META_KEY];if(typeof v3SaveSkills==='function')v3SaveSkills();else save(V3_STORAGE.skills,v3SkillProgress)}
