      const entries={[STORAGE.progress]:nextProgress,[STORAGE.daily]:nextDaily,[STORAGE.prefs]:nextPrefs,[STORAGE.quizHistory]:nextHistory,[V3_STORAGE.skills]:nextSkills,[STORAGE.imported]:nextImported,[STORAGE.session]:nextSession};const before={};for(const k of Object.keys(entries))before[k]=localStorage.getItem(k);try{for(const [k,v] of Object.entries(entries))localStorage.setItem(k,JSON.stringify(v))}catch(e){for(const [k,v] of Object.entries(before)){try{if(v===null)localStorage.removeItem(k);else localStorage.setItem(k,v)}catch(_){}}throw new Error('Penyimpanan gagal; perubahan yang sudah dicoba dibatalkan sejauh yang didukung browser.')}
